import{_ as o,l,o as e,c as s,v as r,p as i,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"canary","description":"","frontmatter":{"title":"canary","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-canary.md","filePath":"cs/stack-canary.md","lastUpdated":1789023840000}'),p={name:"cs/stack-canary.md"};function _(u,a,m,E,A,f){const n=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="canary" tabindex="-1">canary <a class="header-anchor" href="#canary" aria-label="Permalink to &quot;canary&quot;">​</a></h1><div class="epigraph"><p>在返回地址前放一枚秘密值，函数退出前核对。踏过缓冲往往会先改掉它，于是程序选择中止而不是跳进地狱。它检测相邻覆盖，不定义所有内存安全。</p><footer>—— Cowan et al., StackGuard；对照 GCC `-fstack-protector` 的合同</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/stack-smashing-shellcode">栈溢出</a>说明返回地址可被邻接覆盖。缺口是<strong>编译器插入的检测</strong>：canary。不是形式验证，是廉价完整性检查。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若覆盖是从低地址连续写到返回地址，中间的 canary 会被改。核对失败则 abort。缺口：跳过 canary 的写（指针写）、泄漏 canary 值、不保护的函数未插桩。本课不给绕过步骤。</p><h3 id="终止策略" tabindex="-1">终止策略 <a class="header-anchor" href="#终止策略" aria-label="Permalink to &quot;终止策略&quot;">​</a></h3><p>发现后应中止进程。试图「修复栈再继续」会把完整性游戏做坏。</p><p><span class="marginnote">StackGuard。SSP 把 canary 当每线程秘密。Fork 后要重种的讨论点名即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照无保护帧与插桩帧。指出优化可能不给叶子函数插 canary。强调与 NX 正交：一个管执行许可，一个管邻接覆盖检测。</p>',12)),(e(),i(h,null,{default:t(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E5%87%BD%E6%95%B0%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20CAN%5B%22%E5%86%99%E5%85%A5%20canary%22%5D%0A%20%20CAN%20--%3E%20BODY%5B%22%E5%87%BD%E6%95%B0%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20CHK%5B%22%E9%80%80%E5%87%BA%E5%89%8D%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%20AB%5B%22%E5%A4%B1%E8%B4%A5%E5%88%99%E4%B8%AD%E6%AD%A2%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>缓解是概率与覆盖形状上的：连续溢出被抓住，任意写不一定。下一课 ROP：在不可执行栈上仍可能拼已有代码碎片——只讲存在性与防御方向，不给 gadget 序列。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写泄漏 canary 的方法。ROP 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>邻接覆盖返回地址时，中间秘密可被踏到。</li><li>核对失败则中止；不是内存安全。</li><li>任意写与泄漏不在 canary 合同内。</li><li>下一课 ROP（机制，无 gadget 教程）。</li><li>出处：Cowan et al., StackGuard；GCC 栈保护文档。</li></ul>',8))])}const y=o(p,[["render",_]]);export{B as __pageData,y as default};
